def trip(n, slug, op, cat, mode, minutes, policy, prices, times, cap, en, ar, private=None, extras=NOEXTRA, transport=T):
    keys = ("title", "summary", "description", "itinerary", "included", "excluded", "requirements", "meeting_info")
    return dict(id="50000000-0000-0000-0000-0000000000%02d" % n, slug=slug, op=op, cat=CAT[cat], mode=mode, minutes=minutes,
                policy=policy, prices=prices, private=private, extras=extras, transport=transport, times=times, cap=cap,
                images=[], en=dict(zip(keys, en)), ar=dict(zip(keys, ar)))

